(3, 1, 'guided_practice', 15, 'জোড়ায় কাজ পরিচালনা ও শিক্ষার্থীদের সমস্যা সমাধানে সহায়তা', 'জোড়ায় বসে অনুশীলন সমস্যার সমাধান', NULL, NULL, 3, '2026-09-08 15:03:27', '2026-09-08 15:03:27'),
(4, 1, 'conclusion', 10, 'সারসংক্ষেপ মূল্যায়ন ও বাড়ির কাজ প্রদান', 'বাড়ির কাজ লিপিবদ্ধকরণ', NULL, NULL, 4, '2026-09-08 15:03:27', '2026-09-08 15:03:27'),
(5, 2, 'presentation', 20, 'জ্যামিতিক প্রমাণ প্রদর্শন', 'খাতায় চিত্রাঙ্কন ও ধাপ অনুসরণ', NULL, NULL, 1, '2026-09-08 15:03:27', '2026-09-08 15:03:27');
